package co.edu.unbosque.horarios.config;
import co.edu.unbosque.horarios.domain.*; import co.edu.unbosque.horarios.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.jdbc.core.JdbcTemplate; import java.time.LocalDate;
@Configuration public class DemoDataConfig {
 @Bean CommandLineRunner demo(UserRepository users,PasswordEncoder encoder,AcademicPeriodRepository periods,TeacherRepository teachers,CourseRepository courses,ClassroomRepository rooms,SectionRepository sections,ScheduleRepository schedules,JdbcTemplate jdbc){return args->{
  String pwd=encoder.encode("Campus2026!");if(users.findByCorreo("direccion@unbosque.edu.co").isEmpty())users.save(new User("Ana Dirección","direccion@unbosque.edu.co",pwd,Role.DIRECCION));if(users.findByCorreo("area@unbosque.edu.co").isEmpty())users.save(new User("Pepita Área","area@unbosque.edu.co",pwd,Role.COMITE_AREA));if(users.findByCorreo("tactico@unbosque.edu.co").isEmpty())users.save(new User("Tomás Táctico","tactico@unbosque.edu.co",pwd,Role.COMITE_TACTICO));if(users.findByCorreo("estudiante@unbosque.edu.co").isEmpty())users.save(new User("Sofi Estudiante","estudiante@unbosque.edu.co",pwd,Role.ESTUDIANTE));if(users.findByCorreo("docente@unbosque.edu.co").isEmpty())users.save(new User("Laura Docente","docente@unbosque.edu.co",pwd,Role.DOCENTE));if(users.findByCorreo("admin@unbosque.edu.co").isEmpty())users.save(new User("Alex Administrador","admin@unbosque.edu.co",pwd,Role.ADMINISTRADOR));
  if(periods.count()==0){var p=periods.save(new AcademicPeriod("2026-2",LocalDate.of(2026,7,27),LocalDate.of(2026,11,28)));var t1=teachers.save(new Teacher("TH-1042","Laura Méndez","laura@unbosque.edu.co","TIEMPO_COMPLETO","ASISTENTE"));var t2=teachers.save(new Teacher("TH-1098","Daniel Rojas","daniel@unbosque.edu.co","MEDIO_TIEMPO","ASOCIADO"));var c1=courses.save(new Course("SIS-301","Bases de Datos",3,2,true,false));var c2=courses.save(new Course("SIS-205","Ingeniería de Software",3,2,false,true));var c3=courses.save(new Course("MAT-210","Cálculo Vectorial",4,3,false,false));rooms.save(new Classroom("LAB-3","Laboratorio Jacarandá",32,true,true));rooms.save(new Classroom("B-201","Aula Bosque 201",44,false,true));rooms.save(new Classroom("C-105","Aula Cedro 105",36,false,false));sections.save(new Section(c1,p,t1,1,31));sections.save(new Section(c2,p,t2,1,38));sections.save(new Section(c3,p,t1,1,34));sections.save(new Section(c3,p,t2,2,33));schedules.save(new Schedule(p));jdbc.update("insert into docente_curso(id_docente,id_curso) values (?,?),(?,?),(?,?)",t1.getId(),c1.getId(),t1.getId(),c3.getId(),t2.getId(),c2.getId());jdbc.update("insert into docente_curso(id_docente,id_curso) values (?,?)",t2.getId(),c3.getId());for(int day=1;day<=6;day++){jdbc.update("insert into disponibilidad_docente(id_docente,dia_semana,hora_inicio,hora_fin) values (?,?,cast(? as time),cast(? as time))",t1.getId(),day,"07:00","22:00");jdbc.update("insert into disponibilidad_docente(id_docente,dia_semana,hora_inicio,hora_fin) values (?,?,cast(? as time),cast(? as time))",t2.getId(),day,"07:00","22:00");}}
 };}
}
